func maxSubArray(nums []int) int {
    best, cur := nums[0], nums[0]
    for i := 1; i < len(nums); i++ {
        if cur < 0 {
            cur = nums[i] // 前缀为负，重新开始
        } else {
            cur += nums[i]
        }
        if cur > best {
            best = cur
        }
    }
    return best
}
